// slide-02.js - Benchmark Landscape Overview
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: '20+ Benchmarks Spanning Four Capability Domains'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Slide title
  slide.addText("20+ Benchmarks Spanning Four Capability Domains", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  slide.addText("Evaluating 100+ models from leading AI labs", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.secondary
  });

  // 2x2 grid of domains
  const cardW = 4.3, cardH = 1.8;
  const startX = 0.5, startY = 1.5;
  const gapX = 0.4, gapY = 0.35;

  const domains = [
    {
      name: "Agentic",
      color: theme.primary,
      benchmarks: ["SWE Atlas", "SWE-Bench Pro", "MCP Atlas"],
      x: startX, y: startY
    },
    {
      name: "Frontier",
      color: theme.secondary,
      benchmarks: ["Humanity's Last Exam", "EnigmaEval", "MultiChallenge"],
      x: startX + cardW + gapX, y: startY
    },
    {
      name: "Safety",
      color: theme.light,
      benchmarks: ["MASK Honesty", "Fortress", "PropensityBench"],
      x: startX, y: startY + cardH + gapY
    },
    {
      name: "Multimodal",
      color: theme.accent,
      benchmarks: ["AudioMultiChallenge", "VISTA", "VisualToolBench"],
      x: startX + cardW + gapX, y: startY + cardH + gapY
    }
  ];

  domains.forEach(d => {
    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: d.x, y: d.y, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
    });
    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: d.x, y: d.y, w: 0.08, h: cardH,
      fill: { color: d.color }
    });
    // Domain name
    slide.addText(d.name, {
      x: d.x + 0.2, y: d.y + 0.15, w: cardW - 0.3, h: 0.4,
      fontSize: 20, fontFace: "Arial",
      color: d.color, bold: true
    });
    // Benchmarks list
    slide.addText(d.benchmarks.map((b, i) => ({
      text: b,
      options: { bullet: true, breakLine: i < d.benchmarks.length - 1 }
    })), {
      x: d.x + 0.25, y: d.y + 0.6, w: cardW - 0.4, h: 1.1,
      fontSize: 14, fontFace: "Arial",
      color: theme.primary
    });
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "fafaf8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

