// slide-06.js - Safety Alignment Results
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Claude Models: Near-Ceiling MASK Scores, Low Fortress Scores'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Slide title
  slide.addText("Claude Models: Near-Ceiling MASK, Low Fortress", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  slide.addText("Safety Alignment Varies Dramatically by Task Type", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary
  });

  // Two contrasting boxes
  const boxY = 1.4;
  const boxH = 2.6;
  const boxW = 4.3;

  // MASK box - high scores (good)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: boxY, w: boxW, h: boxH,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: boxY, w: boxW, h: 0.5,
    fill: { color: theme.secondary }
  });
  slide.addText("MASK Honesty (Higher = Better)", {
    x: 0.6, y: boxY + 0.08, w: boxW - 0.2, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });

  // Big score callout
  slide.addText("96%", {
    x: 0.7, y: boxY + 0.65, w: 2, h: 1,
    fontSize: 60, fontFace: "Arial",
    color: theme.secondary, bold: true
  });
  slide.addText("Claude Opus 4.6", {
    x: 2.6, y: boxY + 0.85, w: 2, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.primary
  });
  slide.addText("±0.41", {
    x: 2.6, y: boxY + 1.2, w: 2, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.secondary
  });

  // Claude Sonnet 4 score
  slide.addText("Claude Sonnet 4: 96.13%", {
    x: 0.7, y: boxY + 1.7, w: 3.5, h: 0.35,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary
  });
  slide.addText("Near-ceiling performance on honesty benchmark", {
    x: 0.7, y: boxY + 2.05, w: 3.5, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary
  });

  // Fortress box - low scores (concerning)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: boxY, w: boxW, h: boxH,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: boxY, w: boxW, h: 0.5,
    fill: { color: theme.light }
  });
  slide.addText("Fortress Security (Higher = Better)", {
    x: 5.3, y: boxY + 0.08, w: boxW - 0.2, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });

  // Big score callout
  slide.addText("8%", {
    x: 5.4, y: boxY + 0.65, w: 2, h: 1,
    fontSize: 60, fontFace: "Arial",
    color: theme.light, bold: true
  });
  slide.addText("Best score", {
    x: 7.3, y: boxY + 0.85, w: 2, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.primary
  });
  slide.addText("±1.93", {
    x: 7.3, y: boxY + 1.2, w: 2, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.secondary
  });

  // Score range
  slide.addText("All models: 8–13% range — substantial safety gaps", {
    x: 5.4, y: boxY + 1.7, w: 3.8, h: 0.35,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary
  });
  slide.addText("PropensityBench: o3 scores 10.5 (lower=better)", {
    x: 5.4, y: boxY + 2.05, w: 3.8, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary
  });

  // Key insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.25, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 10 }
  });
  slide.addText("Claude dominates safety benchmarks but Fortress reveals critical vulnerabilities across all models", {
    x: 0.6, y: 4.3, w: 8.8, h: 0.45,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, align: "center", valign: "middle"
  });

  // Source
  slide.addText("Source: Scale Labs SEAL Leaderboard", {
    x: 0.5, y: 5.2, w: 4, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "fafaf8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

