// slide-08.js - Key Takeaways
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: Specialization Is the New Frontier'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Slide title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 36, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  slide.addText("Specialization Is the New Frontier", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.secondary
  });

  // Takeaway cards
  const takeaways = [
    {
      num: "1",
      text: "GPT-5.4 leads agentic coding and frontier reasoning — OpenAI dominates what it was built for"
    },
    {
      num: "2",
      text: "Gemini sweeps all audio and vision-language benchmarks — Google's multimodal strategy excels"
    },
    {
      num: "3",
      text: "Claude leads safety and professional reasoning with 96%+ on MASK honesty benchmark"
    },
    {
      num: "4",
      text: "Key benchmarks (HLE 44%, EnigmaEval 24%, SciPredict 25%) remain far from saturation"
    },
    {
      num: "5",
      text: "New entrant Muse Spark ranks top 3 on 6+ benchmarks including #1 on MultiChallenge at 75.5%"
    }
  ];

  const cardStartY = 1.4;
  const cardH = 0.65;
  const cardGap = 0.15;

  takeaways.forEach((t, i) => {
    const y = cardStartY + i * (cardH + cardGap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 9, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 3, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.7, y: y + 0.15, w: 0.35, h: 0.35,
      fill: { color: theme.accent }
    });
    slide.addText(t.num, {
      x: 0.7, y: y + 0.15, w: 0.35, h: 0.35,
      fontSize: 14, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Takeaway text
    slide.addText(t.text, {
      x: 1.2, y: y, w: 8.1, h: cardH,
      fontSize: 13, fontFace: "Arial",
      color: theme.primary, valign: "middle"
    });
  });

  // Closing statement
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 9, h: 0.45,
    fill: { color: theme.primary }
  });
  slide.addText("No single model wins everywhere — specialization defines the frontier landscape", {
    x: 0.6, y: 5.05, w: 8.8, h: 0.35,
    fontSize: 13, fontFace: "Arial",
    color: "FFFFFF", align: "center", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "fafaf8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

