const PptxGenJS = require("pptxgenjs");

const theme = {
  primary: "264653",   // deep teal - titles
  secondary: "2a9d8f", // teal - body/secondary text
  accent: "e9c46a",    // golden yellow - highlights
  light: "f4a261",     // sandy orange - light accent
  bg: "fafaf8"         // warm off-white background
};

const slideConfig = {
  title: "Scale SEAL Leaderboards",
  type: "cover",
  pageNumber: null
};

function createSlide() {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_16x9";
  pptx.defineLayout({ name: "CUSTOM", width: 10, height: 5.625 });
  pptx.layout = "CUSTOM";

  const slide = pptx.addSlide();

  // Background
  slide.background = { color: theme.bg };

  // Left accent bar
  slide.addShape(pptx.ShapeType.rect, {
    x: 0,
    y: 0,
    w: 0.15,
    h: 5.625,
    fill: { color: theme.primary }
  });

  // Bottom accent stripe
  slide.addShape(pptx.ShapeType.rect, {
    x: 0,
    y: 4.8,
    w: 10,
    h: 0.825,
    fill: { color: theme.primary }
  });

  // Scale Labs branding - top right
  slide.addText("Scale Labs", {
    x: 7.5,
    y: 0.3,
    w: 2.2,
    h: 0.4,
    fontSize: 14,
    color: theme.secondary,
    bold: true,
    align: "right"
  });

  // Main title
  slide.addText("Scale SEAL Leaderboards", {
    x: 0.6,
    y: 1.4,
    w: 8.8,
    h: 1.0,
    fontSize: 44,
    fontFace: "Arial",
    color: theme.primary,
    bold: true
  });

  // Subtitle
  slide.addText("Frontier Model Performance Across 20+ AI Benchmarks", {
    x: 0.6,
    y: 2.4,
    w: 8.8,
    h: 0.6,
    fontSize: 22,
    fontFace: "Arial",
    color: theme.secondary
  });

  // Accent line under subtitle
  slide.addShape(pptx.ShapeType.rect, {
    x: 0.6,
    y: 3.1,
    w: 2.5,
    h: 0.05,
    fill: { color: theme.accent }
  });

  // Note text
  slide.addText("100+ models evaluated  •  Agentic  •  Frontier  •  Safety  •  Multimodal", {
    x: 0.6,
    y: 3.4,
    w: 8.8,
    h: 0.5,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.light
  });

  // SEAL branding on bottom bar
  slide.addText("SEAL", {
    x: 0.6,
    y: 5.0,
    w: 1.5,
    h: 0.5,
    fontSize: 24,
    fontFace: "Arial",
    color: theme.accent,
    bold: true
  });

  return pptx;
}

// Run standalone for preview
if (require.main === module) {
  const pptx = createSlide();
  pptx.writeFile({ fileName: "/app/slides/output/slide-01-preview.pptx" })
    .then(() => console.log("Created: slide-01-preview.pptx"))
    .catch(err => console.error(err));
}

module.exports = { createSlide, slideConfig };

