// slide-01.js - Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Scale SEAL Leaderboards'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: theme.primary }
  });

  // Bottom accent stripe
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.8, w: 10, h: 0.825,
    fill: { color: theme.primary }
  });

  // Scale Labs branding - top right
  slide.addText("Scale Labs", {
    x: 7.5, y: 0.3, w: 2.2, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, bold: true, align: "right"
  });

  // Main title
  slide.addText("Scale SEAL Leaderboards", {
    x: 0.6, y: 1.4, w: 8.8, h: 1.0,
    fontSize: 44, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("Frontier Model Performance Across 20+ AI Benchmarks", {
    x: 0.6, y: 2.4, w: 8.8, h: 0.6,
    fontSize: 22, fontFace: "Arial",
    color: theme.secondary
  });

  // Accent line under subtitle
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.1, w: 2.5, h: 0.05,
    fill: { color: theme.accent }
  });

  // Note text
  slide.addText("100+ models evaluated  •  Agentic  •  Frontier  •  Safety  •  Multimodal", {
    x: 0.6, y: 3.4, w: 8.8, h: 0.5,
    fontSize: 14, fontFace: "Arial",
    color: theme.light
  });

  // SEAL branding on bottom bar
  slide.addText("SEAL", {
    x: 0.6, y: 5.0, w: 1.5, h: 0.5,
    fontSize: 24, fontFace: "Arial",
    color: theme.accent, bold: true
  });

  // NO page number badge on cover page
  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "fafaf8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

